package ch.jalu.configme.configurationdata;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.*;

public class CommentsConfigurationTest {

    @Test
    public void setComment_NewSingleLineCommentTextTest() {
        String path = "testPath";
        String comment = "The single comment line";
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, comment);

        Map<String, List<String>> comments = commentsConfiguration.getAllComments();

        assertTrue(comments.containsKey(path));
        assertEquals(Collections.singletonList(comment), comments.get(path));
    }

    @Test
    public void setComment_NewMultipleCommentLinesTest() {
        String path = "testPath";
        String[] commentLines = new String[] {"Line 1", "Line 2", "Line 3"};
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, commentLines);

        Map<String, List<String>> comments = commentsConfiguration.getAllComments();

        assertTrue(comments.containsKey(path));
        assertEquals(Arrays.asList(commentLines), comments.get(path));
    }

    @Test
    public void setComment_NullPath_FailTest() {
        String comment = "The single comment line";

        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        try {
            commentsConfiguration.setComment(null, comment);
            fail("Should have thrown a NullPointerException");
        } catch (NullPointerException e) {
            // expected
        }
    }

    @Test
    public void setComment_PreventModifyingCommentsTest() {
        String path = "testPath";
        String comment = "The single comment line";
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        commentsConfiguration.setComment(path, comment);

        Map<String, List<String>> comments = commentsConfiguration.getAllComments();

        try {
            comments.put("testKey", Collections.singletonList("testValue"));
            fail("Should have thrown an UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }

        try {
            comments.get(path).add("Impossible comment");
            fail("Should have thrown an UnsupportedOperationException");
        } catch (UnsupportedOperationException e) {
            // expected
        }
    }

    @Test
    public void getAllComments_WithPredefinedCommentsTest() {
        Map<String, List<String>> predefinedComments = new HashMap<>();
        predefinedComments.put("path1", Collections.singletonList("comment1"));
        predefinedComments.put("path2", Collections.singletonList("comment2"));
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration(predefinedComments);

        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();

        assertEquals(predefinedComments, allComments);
    }

    @Test
    public void getAllComments_WithOutAnyCommentTest() {
        CommentsConfiguration commentsConfiguration = new CommentsConfiguration();
        Map<String, List<String>> allComments = commentsConfiguration.getAllComments();

        assertTrue(allComments.isEmpty());
    }
}
